    def _home(self, t: dict[str, str], mount: str) -> str:
        cards = "".join(f'<a class="doc-card" href="{mount}{href}"><h3>{escape(t[key])}</h3><p>{escape(t[key + "_text"])}</p><span class="card-index">0{index} →</span></a>' for index, (key, href) in enumerate((("quickstart", "/guide"), ("deployments", "/api"), ("events", "/api"), ("access", "/faq")), 1))
        popular = "".join(f'<li><a href="{mount}{href}">{escape(t[key])}</a></li>' for key, href in (("popular_1", "/guide"), ("popular_2", "/api"), ("popular_3", "/api"), ("popular_4", "/faq")))
        return f'''<p class="eyebrow">{escape(t["eyebrow"])}</p><h1>{escape(t["headline"])}</h1><p class="lede">{escape(t["lead"])}</p><form class="search-form" action="{mount}/" method="get"><label><input type="search" name="q" autocomplete="off" placeholder="{escape(t["search"])}" aria-label="{escape(t["search"])}"></label><button type="submit">{escape(t["search_button"])}</button></form><p class="help-text">{escape(t["help"])}</p><div class="section-heading"><h2>{escape(t["browse"])}</h2><span class="count">04 {escape(t["articles"])}</span></div><section class="card-grid" aria-label="{escape(t["browse"])}">{cards}</section><section class="home-lower"><div><div class="section-heading"><h2>{escape(t["popular"])}</h2><span class="count">{escape(t["updated"])}</span></div><ol class="popular-list">{popular}</ol></div><aside class="quiet-panel"><h3>{escape(t["guide_start"])}</h3><p>{escape(t["guide_start_p"])}</p></aside></section>'''

    def _guide(self, t: dict[str, str], lang: str, mount: str) -> str:
        limits_heading = "guide.sections.limits.title" if lang == "ar" else t["guide_limits"]
        request = 'northstar deployments create \\\n+  --project prj_atlas \\\n+  --environment production \\\n+  --version 2026.08.18'
        response = '{\n  "id": "dep_01J6Q6R5",\n  "status": "queued",\n  "environment": "production"\n}'
        return f'''<div class="article-layout"><article class="article"><p class="eyebrow">{escape(t["guide"])}</p><h1>{escape(t["guide_title"])}</h1><p class="lede">{escape(t["guide_lead"])}</p><p class="meta">{escape(t["updated"])} · 6 min</p><h2 id="before-you-begin">{escape(t["guide_start"])}</h2><p>{escape(t["guide_start_p"])}</p><div class="callout"><h3>{escape(t["note_title"])}</h3><p>{escape(t["note"])}</p></div><div class="code-block"><div class="code-head"><span>shell</span><button type="button">{escape(t["copy"])}</button></div><pre><code>{escape(request)}</code></pre></div><h2 id="limits">{escape(limits_heading)}</h2><p>{escape(t["limits_text"])}</p><div class="code-block"><div class="code-head"><span>json</span><button type="button">{escape(t["copy"])}</button></div><pre><code>{escape(response)}</code></pre></div><h2 id="observe">{escape(t["guide_events"])}</h2><p>{escape(t["events_text"])}</p></article><aside class="toc"><h2>{escape(t["on_this_page"])}</h2><ol><li><a href="{mount}/guide#before-you-begin">{escape(t["guide_start"])}</a></li><li><a href="{mount}/guide#limits">{escape(t["guide_limits"])}</a></li><li><a href="{mount}/guide#observe">{escape(t["guide_events"])}</a></li></ol></aside></div>'''

    def _api(self, t: dict[str, str]) -> str:
        request = 'POST /v1/projects/prj_atlas/deployments\nAuthorization: Bearer ns_live_••••\nContent-Type: application/json\n\n{\n  "environment": "production",\n  "version": "2026.08.18"\n}'
        response = 'HTTP/1.1 201 Created\n\n{\n  "id": "dep_01J6Q6R5",\n  "status": "queued",\n  "created_at": "2026-08-18T09:42:16Z"\n}'
        rows = (("POST", "/v1/projects/{project_id}/deployments", "create_deployment"), ("GET", "/v1/deployments/{deployment_id}", "get_deployment"), ("GET", "/v1/projects/{project_id}/deployments", "list_deployments"))
        endpoint_rows = "".join(f'<div class="endpoint-row"><span class="method">{method}</span><code class="path">{escape(route)}</code><p>{escape(t[key])}</p></div>' for method, route, key in rows)
        params = "".join(f'<tr><td><span class="param-name">{escape(name)}</span><span class="badge">{escape(kind)}</span></td><td>{escape(description)}</td></tr>' for name, kind, description in ((t["path_param"], t["required"], t["path_param_text"]), (t["body_param"], t["required"], t["body_param_text"]), (t["body_param2"], t["optional"], t["body_param2_text"])))
        return f'''<p class="eyebrow">{escape(t["api"])}</p><h1>{escape(t["api_title"])}</h1><p class="lede">{escape(t["api_lead"])}</p><section class="endpoint-list" aria-label="{escape(t["endpoint"])}"><div class="endpoint-row"><span class="count">{escape(t["endpoint"])}</span><span class="count">Path</span><span class="count">{escape(t["description"])}</span></div>{endpoint_rows}</section><section class="api-section"><div class="callout"><h3>{escape(t["note_title"])}</h3><p>{escape(t["api_note"])}</p></div><h2>{escape(t["parameters"])}</h2><table class="param-table"><thead><tr><th scope="col">{escape(t["parameters"])}</th><th scope="col">{escape(t["description"])}</th></tr></thead><tbody>{params}</tbody></table></section><section class="api-section"><h2>{escape(t["create_deployment"])}</h2><div class="sample-grid"><div class="code-block"><div class="code-head"><span>{escape(t["request"])} · json</span><button type="button">{escape(t["copy"])}</button></div><pre><code>{escape(request)}</code></pre></div><div class="code-block"><div class="code-head"><span>{escape(t["response"])} · json</span><button type="button">{escape(t["copy"])}</button></div><pre><code>{escape(response)}</code></pre></div></div></section>'''

    def _faq(self, t: dict[str, str], mount: str) -> str:
        questions = "".join(f'<details><summary>{escape(t[key])}</summary><p>{escape(t[key + "a"])}</p></details>' for key in ("faq_1", "faq_2", "faq_3", "faq_4"))
        related = "".join(f'<li><a href="{mount}/faq">{escape(t[key])}</a></li>' for key in ("related_1", "related_2", "related_3"))
        return f'''<div class="faq-layout"><div><p class="eyebrow">{escape(t["faq"])}</p><h1>{escape(t["faq_title"])}</h1><p class="lede">{escape(t["faq_lead"])}</p><section class="faq-list">{questions}</section></div><aside class="related-questions"><h2>{escape(t["related"])}</h2><ul>{related}</ul></aside></div>'''
